                let (yv, yt) = Self::lower_expr(out, &args[1], ctx, Some("i32"));
                let yc = Self::coerce_scalar(out, ctx, &yv, &yt, "i32");
                let (sv, st) = Self::lower_expr(out, &args[2], ctx, Some("i32"));
