                let (cv, ct) = Self::lower_expr(out, &args[3], ctx, Some("i32"));
                let cc = Self::coerce_scalar(out, ctx, &cv, &ct, "i32");
                let (tv, tt) = Self::lower_expr(out, &args[4], ctx, Some("ptr"));
